function signMegaplay(u) {
  try {
    const x = new URL(u); const m = x.pathname.match(/\/([a-f0-9]{32})\/([a-f0-9]{32})\//i);
    if (!m) return u;
    const p = utf8enc(Math.floor(Date.now() / 1000) + 90 + "|" + m[1].toLowerCase() + "/" + m[2].toLowerCase());
    const sig = hmac256("MpCdnT0k3n!9f2K#xQ7vL5mR8wN1pY4s", p);
    const q = x.search ? x.search + "&" : "?";
    return x.href.split("?")[0] + q + "token=" + b64url(p) + "." + b64url(sig);
  } catch (e) { return u; }
}

async function fetchT(url, opts, timeoutMs) {
  const c = new AbortController(); const t = setTimeout(() => c.abort(), timeoutMs || 8000);
  try {
    const r = await fetch(url, { method: (opts && opts.method) || "GET", headers: { "User-Agent": UA, "Accept": "*/*", ...((opts && opts.headers) || {}) }, body: opts && opts.body, signal: c.signal });
    return { status: r.status, ok: r.ok, text: await r.text() };
  } catch (e) { return { status: 0, ok: false, text: "" }; } finally { clearTimeout(t); }
}

async function getText(url, headers, timeoutMs) { const r = await fetchT(url, { headers }, timeoutMs); return r.ok ? r.text : ""; }
async function getJson(url, headers, timeoutMs) {
  const r = await fetchT(url, { headers }, timeoutMs);
  if (!r.ok) return null;
  try { return JSON.parse(r.text); } catch (e) { return null; }
}

async function extractMegaplay(anilistId, episode, lang) {
  const embedUrl = MP_BASE + "/stream/ani/" + anilistId + "/" + episode + "/" + lang;
  log("embed " + embedUrl);
  const html = await getText(embedUrl, { "Referer": MP_REFERER }, 8000);
  if (!html) return null;
  const dataIdMatch = html.match(/id="megaplay-player"[^>]*data-id="(\d+)"/i) || html.match(/data-id="(\d+)"/i);
  if (!dataIdMatch) return null;
  const dataId = dataIdMatch[1];
  const json = await getJson(MP_BASE + "/stream/getSources?id=" + dataId, { "Referer": MP_BASE + "/", "X-Requested-With": "XMLHttpRequest" }, 8000);
  if (!json) return null;
  let fileUrl = ""; let tracks = json.tracks || [];
  if (json.enc) {
    try {
      const k = new Uint8Array(32); k.set(utf8enc("i?LMTAx0Q6,:}50U"));
      const iv = utf8enc("W0;27ToaUpl_P%'c");
      const parsed = JSON.parse(utf(aesCbcDec(b64dec(json.enc), k, iv)));
      fileUrl = parsed.file; if (parsed.tracks && parsed.tracks.length > 0) tracks = parsed.tracks;
    } catch (e) { log("decrypt failed: " + e.message); return null; }
  } else { fileUrl = json.file || (json.sources && json.sources.file); }
  if (!fileUrl) return null;
  fileUrl = signMegaplay(fileUrl);
  const subtitles = [];
  for (let i = 0; i < tracks.length; i++) {
    const t = tracks[i];
    if (t.kind === "captions" && t.file) {
      let langCode = "en"; const lbl = String(t.label || "").toLowerCase();
      if (lbl.includes("spanish")) langCode = "es"; else if (lbl.includes("portuguese")) langCode = "pt"; else if (lbl.includes("french")) langCode = "fr"; else if (lbl.includes("german")) langCode = "de"; else if (lbl.includes("arabic")) langCode = "ar"; else if (lbl.includes("italian")) langCode = "it"; else if (lbl.includes("russian")) langCode = "ru"; else if (lbl.includes("english")) langCode = "en"; else langCode = lbl.substring(0, 2);
      subtitles.push({ url: t.file, name: t.label || "Unknown", language: langCode, format: t.file.endsWith(".vtt") ? "vtt" : "srt", default: t.default === true, headers: { "User-Agent": UA, "Referer": MP_BASE + "/" } });
    }
  }
  return { name: "Megaplay", title: "Megaplay [" + lang.toUpperCase() + "]", url: fileUrl, quality: "auto", headers: { "User-Agent": UA, "Referer": MP_BASE + "/" }, subtitles: subtitles, provider: "megaplay", type: fileUrl.indexOf(".m3u8") >= 0 ? "hls" : "mp4" };
}

function getSetting(settings, names, fallback) {
  if (!settings || typeof settings !== "object") return fallback;
  for (let i = 0; i < names.length; i++) { const n = names[i]; if (Object.prototype.hasOwnProperty.call(settings, n) && settings[n] !== undefined && settings[n] !== null) return settings[n]; }
  return fallback;
}

function modes(settings) {
  const sub = getSetting(settings, ["sub", "Sub", "subtitle"], true) !== false;
  const dub = getSetting(settings, ["dub", "Dub"], false) === true;
  const out = []; if (sub) out.push("sub"); if (dub) out.push("dub");
  return out.length ? out : ["sub"];
}

async function getStreams(tmdbId, mediaType, season, episode, settings) {
  try {
    mediaType = String(mediaType || "tv").toLowerCase();
    const id = String(tmdbId || "").trim();
    if (!id || !/^\d+$/.test(id)) return [];
    if (mediaType !== "movie" && mediaType !== "tv") return [];
    const s = Number(season); const e = Number(episode) || 1; const sNorm = Number.isFinite(s) ? s : 1;
    log("resolve tmdb=" + id + " " + mediaType + " S" + sNorm + "E" + e);
    const resolved = resolveMapping(id, sNorm, e);
    if (!resolved) { log("no TVDB mapping"); return []; }
    log("mapped anilist=" + resolved.anilistId + " absEp=" + resolved.absoluteEpisode);
    const langs = modes(settings); const streams = [];
    for (const lang of langs) {
      const stream = await extractMegaplay(resolved.anilistId, resolved.absoluteEpisode, lang);
      if (stream) streams.push(stream);
    }
    log("emitting " + streams.length + " stream(s)");
    return streams;
  } catch (err) { log("ERROR " + (err && err.message || err)); return []; }
}

module.exports = { getStreams };
